<script setup>
import { computed, reactive, ref, watch, onUnmounted } from 'vue'
import { X, Trash2, Plus, Check, Paperclip, Archive, MessageSquare } from 'lucide-vue-next'
import { useWorkboard } from '../stores/workboard'
import DependencyPicker from './DependencyPicker.vue'
const props=defineProps({ task:Object, column:Number, sprint:Number })
const emit=defineEmits(['close'])
const store=useWorkboard()
const form=reactive({title:props.task?.title ?? '',description:props.task?.description ?? '',column:props.task?.column ?? props.column,sprint:props.task?.sprint ?? props.sprint ?? null,priority:props.task?.priority ?? 'medium',due_date:props.task?.due_date ?? '',assignee:props.task?.assignee ?? null,labels:[...(props.task?.labels ?? [])],dependencies:[...(props.task?.dependencies ?? [])],blocked:props.task?.blocked ?? false,blocked_reason:props.task?.blocked_reason ?? ''})
const revision=ref(props.task?.board_revision ?? store.board.revision),confirm=ref(false),tab=ref('details'),itemTitle=ref(''),comment=ref(''),editingComment=ref(null)
watch(()=>store.lastUndo,event=>{if(event?.board===store.selected && event.previousRevision===revision.value)revision.value=event.revision})
const liveTask=computed(()=>store.details[props.task?.id] ?? props.task)
onUnmounted(()=>{if(props.task)delete store.details[props.task.id]})
const tasks=computed(()=>store.board?.columns.flatMap(c=>c.tasks).filter(t=>t.id!==props.task?.id) ?? [])
const sprintOptions=computed(()=>store.board?.sprints.filter(s=>s.status!=='completed' || s.id===form.sprint) ?? [])
async function reload() { const current=await store.fetchTask(props.task.id); if(current) for(const key of Object.keys(form)) form[key]=key==='due_date' ? current[key] ?? '' : Array.isArray(current[key]) ? [...current[key]] : current[key];revision.value=current.board_revision;store.error='' }
async function save() { await store.run(async()=>{await store.mutate(`tasks/${props.task ? `${props.task.id}/` : ''}`,props.task?'PATCH':'POST',{...form,due_date:form.due_date || null},revision.value);emit('close')}) }
async function remove() { await store.run(async()=>{ const id=props.task.id;await store.mutate(`tasks/${id}/`,'DELETE',undefined,revision.value);store.offerUndo('Tarefa enviada para a lixeira.',()=>store.mutate(`tasks/${id}/restore/`,'POST',{}));emit('close') }) }
async function archive() { await store.run(async()=>{const id=props.task.id,previous=liveTask.value.archived;await store.mutate(`tasks/${id}/`,'PATCH',{archived:!previous},revision.value);store.offerUndo(previous?'Tarefa desarquivada.':'Tarefa arquivada.',()=>store.mutate(`tasks/${id}/`,'PATCH',{archived:previous}));emit('close')}) }
async function change(path,method,data) { const success=await store.run(async()=>{await store.mutate(path,method,data,revision.value);revision.value=store.board.revision});return success }
async function addItem() { if(await change('checklist/','POST',{task:props.task.id,title:itemTitle.value})) itemTitle.value='' }
async function editItem(item) {const title=window.prompt('Editar item do checklist',item.title);if(title?.trim())await change(`checklist/${item.id}/`,'PATCH',{title})}
async function deleteItem(item) { if(!window.confirm('Excluir este item de checklist?')) return; const data={task:props.task.id,title:item.title,done:item.done};if(await change(`checklist/${item.id}/`,'DELETE'))store.offerUndo('Item excluído.',()=>store.mutate('checklist/','POST',data)) }
async function saveComment() { if(await change(`comments/${editingComment.value ? `${editingComment.value}/` : ''}`,editingComment.value?'PATCH':'POST',{task:props.task.id,content:comment.value})) {comment.value='';editingComment.value=null} }
async function deleteComment(item) { if(!window.confirm('Excluir este comentário?'))return;if(await change(`comments/${item.id}/`,'DELETE'))store.offerUndo('Comentário excluído.',()=>store.mutate('comments/','POST',{task:props.task.id,content:item.content})) }
async function upload(event) { const file=event.target.files?.[0];if(!file)return;const data=new FormData();data.append('task',props.task.id);data.append('file',file);await change('attachments/','POST',data);event.target.value='' }
async function deleteAttachment(item) {
  if(!window.confirm('Excluir este anexo? Será possível desfazer por 30 segundos.'))return
  await store.run(async()=>{
    const response=await fetch(item.download_url,{credentials:'same-origin'})
    if(!response.ok)throw new Error('Não foi possível preparar a recuperação do anexo.')
    const blob=await response.blob(),task=props.task.id
    await store.mutate(`attachments/${item.id}/`,'DELETE',undefined,revision.value)
    revision.value=store.board.revision
    store.offerUndo('Anexo excluído.',()=>{const data=new FormData();data.append('task',task);data.append('file',blob,item.name);return store.mutate('attachments/','POST',data)})
  })
}
function timestamp(value) {return new Date(value).toLocaleString('pt-BR')}
</script>

<template>
  <div class="modal-backdrop" @click.self="!store.busy && emit('close')" @keydown.esc="!store.busy && emit('close')"><section v-dialog class="modal task-dialog" role="dialog" aria-modal="true" aria-labelledby="task-dialog-title"><div class="modal-heading"><h2 id="task-dialog-title">{{confirm?'Excluir tarefa':task?'Editar tarefa':'Nova tarefa'}}</h2><button aria-label="Fechar" :disabled="store.busy" @click="emit('close')"><X :size="20"/></button></div>
    <template v-if="confirm"><p>A tarefa será enviada para a lixeira e poderá ser restaurada. As dependências precisam ser removidas antes da exclusão.</p><p v-if="store.error" class="error" role="alert">{{store.error}}</p><div class="modal-actions"><button class="secondary" @click="confirm=false">Cancelar</button><button class="danger" :disabled="store.busy" @click="remove">Confirmar exclusão</button></div></template>
    <template v-else><div v-if="task" class="detail-tabs"><button :class="{active:tab==='details'}" @click="tab='details'">Detalhes</button><button :class="{active:tab==='comments'}" @click="tab='comments'">Comentários ({{liveTask?.comments.length ?? 0}})</button><button :class="{active:tab==='history'}" @click="tab='history'">Histórico</button></div>
    <form v-if="tab==='details'" @submit.prevent="save"><fieldset :disabled="!store.canWrite || store.busy" class="plain-fieldset"><label>Título<input v-model="form.title" autofocus required maxlength="200" placeholder="O que vamos construir?"></label><label>Descrição<textarea v-model="form.description" maxlength="5000" rows="3" placeholder="Um pouco de contexto..."></textarea></label><div class="form-row"><label>Coluna<select v-model="form.column" aria-label="Coluna da tarefa"><option v-for="col in store.board.columns" :key="col.id" :value="col.id">{{col.title}}</option></select></label><label>Sprint<select v-model="form.sprint" aria-label="Sprint da tarefa"><option :value="null">Backlog — sem sprint</option><option v-for="s in sprintOptions" :key="s.id" :value="s.id">{{s.title}}</option></select></label></div><div class="form-row"><label>Prioridade<select v-model="form.priority"><option value="low">Baixa</option><option value="medium">Média</option><option value="high">Alta</option></select></label><label>Prazo<input v-model="form.due_date" type="date"></label></div><label>Responsável<select v-model="form.assignee" aria-label="Responsável"><option :value="null">Sem responsável</option><option v-for="m in store.board.members" :key="m.user" :value="m.user">{{m.user_name}}</option></select></label><div v-if="store.board.labels.length"><span class="field-title">Etiquetas</span><div class="label-options"><label v-for="label in store.board.labels" :key="label.id" class="check-label"><input v-model="form.labels" type="checkbox" :value="label.id"><span class="label-chip" :style="{'--label-color':label.color}">{{label.title}}</span></label></div></div><DependencyPicker v-model="form.dependencies" :task-id="task?.id"/><label class="check-label"><input v-model="form.blocked" type="checkbox">Tarefa bloqueada</label><label v-if="form.blocked">Motivo do bloqueio<input v-model="form.blocked_reason" required maxlength="500" placeholder="O que impede o andamento?"></label></fieldset>
    <div v-if="task" class="task-extras"><h3>Checklist</h3><div v-for="item in liveTask?.checklist" :key="item.id" class="checklist-row"><label class="check-label"><input type="checkbox" :checked="item.done" :disabled="!store.canWrite || store.busy" @change="change(`checklist/${item.id}/`,'PATCH',{done:!item.done})"><span :class="{struck:item.done}">{{item.title}}</span></label><button v-if="store.canWrite" type="button" :aria-label="`Editar item ${item.title}`" :disabled="store.busy" @click="editItem(item)">Editar</button><button v-if="store.canWrite" type="button" :aria-label="`Excluir item ${item.title}`" :disabled="store.busy" @click="deleteItem(item)"><Trash2 :size="14"/></button></div><div v-if="store.canWrite" class="inline-form"><input v-model="itemTitle" maxlength="200" aria-label="Novo item do checklist" placeholder="Adicionar um passo…" @keydown.enter.prevent="itemTitle.trim() && addItem()"><button type="button" class="secondary" :disabled="!itemTitle.trim() || store.busy" @click="addItem"><Plus :size="16"/></button></div><h3>Anexos <small>Até 10 MB por arquivo</small></h3><div v-for="file in liveTask?.attachments" :key="file.id" class="attachment-row"><a :href="file.download_url" download><Paperclip :size="14"/>{{file.name}}</a><button v-if="store.canWrite" type="button" :aria-label="`Excluir anexo ${file.name}`" :disabled="store.busy" @click="deleteAttachment(file)"><Trash2 :size="14"/></button></div><label v-if="store.canWrite" class="upload-label">Adicionar anexo<input type="file" :disabled="store.busy" @change="upload"></label></div>
    <p v-if="store.error" class="error" role="alert">{{store.error}}<button v-if="task" type="button" class="text-button" @click="reload">Recarregar dados da tarefa</button></p><div v-if="store.canWrite" class="modal-actions"><button v-if="task" type="button" class="danger" :disabled="store.busy" @click="confirm=true"><Trash2 :size="16"/> Excluir</button><button v-if="task" type="button" class="secondary" :disabled="store.busy" @click="archive"><Archive :size="16"/>{{liveTask?.archived?'Desarquivar':'Arquivar'}}</button><button class="primary" :disabled="store.busy">{{store.busy?'Salvando…':'Salvar'}}</button></div></form>
    <section v-else-if="tab==='comments'" class="comments-panel"><p v-if="!liveTask?.comments.length">Converse sobre decisões e próximos passos.</p><article v-for="item in liveTask?.comments" :key="item.id" class="comment-item"><div><strong>{{item.author_name}}</strong><small>{{timestamp(item.created_at)}}</small></div><p>{{item.content}}</p><div v-if="store.canWrite && (item.author_name===store.user.username || store.canManage)"><button @click="editingComment=item.id;comment=item.content">Editar</button><button @click="deleteComment(item)">Excluir</button></div></article><form v-if="store.canWrite" @submit.prevent="saveComment"><label>{{editingComment?'Editar comentário':'Novo comentário'}}<textarea v-model="comment" required maxlength="3000" rows="3"></textarea></label><p v-if="store.error" class="error" role="alert">{{store.error}}</p><div class="modal-actions"><button v-if="editingComment" type="button" @click="editingComment=null;comment=''">Cancelar edição</button><button class="primary" :disabled="store.busy || !comment.trim()"><MessageSquare :size="16"/>{{editingComment?'Salvar comentário':'Comentar'}}</button></div></form></section>
    <section v-else class="activity-list"><article v-for="item in liveTask?.activities" :key="item.id"><strong>{{item.actor_name}}</strong><p>{{item.message}}</p><small>{{timestamp(item.created_at)}}</small></article><p v-if="!liveTask?.activities.length">Nenhuma atividade registrada.</p></section></template>
  </section></div>
</template>
